add('方案二　权限知识库','NAS资料变成按员工权限可查询的答案','检索结果带原文位置，同一接口可供Agent调用','flow','文件与有效权限一起进入知识库。可信身份决定可检索范围，候选内容进入重排与模型前完成授权过滤，引用和原文下载再次检查权限。Word、PDF、PPT、Excel按文档结构解析，保持页码、表格、单位和版本。','这套链路可以购买企业平台，也可以由团队自己建设。','参考设计；RAG主流程在此完整介绍。',[SRC['milvus']],nodes=[['NAS','文件与有效ACL'],['入库索引','解析／向量／关键词'],['授权检索','身份过滤＋重排'],['回答引用','Qwen27＋原文入口']],callout='权限跟随内容、引用和导出；撤权时同步更新索引与缓存。')
add('方案二　平台选择','Onyx与自建方案，区别在交付和维护分工','两条路线比较同一套模型资源和权限验收','table','Onyx企业平台提供私有部署、管理和企业功能，NAS适配及权限映射需纳入交付。自建以Milvus检索为核心，由应用实现身份、ACL同步、检索过滤、引用与管理。Open WebUI作为入口。前端简单，主要工作在接入、更新和权限。','费用与响应都需要放在一套明确的硬件配置上比较。','Onyx企业授权按实际席位与范围询价，记为L。',[SRC['onyx'],SRC['milvus']],cols=['部分','Onyx Enterprise','Milvus＋自建RAG'],rows=[['入口与管理','平台搜索、问答、管理','Open WebUI＋管理接口'],['资料与权限','连接器＋约定的NAS适配','扫描、ACL求值、身份同步'],['索引与检索','所选版本的原生组件','Milvus向量＋关键词检索'],['模型服务','Qwen27内部端点','同一Qwen27内部端点'],['维护责任','平台方／集成商＋内部IT','内部应用与运维团队']],callout='选择平台之前，先明确NAS连接、撤权同步和引用访问的交付范围。')
add('方案二　资源与投入','短问答和长会话使用不同容量预算','四张6000D中三张回答、一张辅助，两台CPU节点负责应用与检索','table','固定主方案为4×6000D 84GB整机及两台CPU节点，硬件74至141万。Qwen27 FP8权重，KV为完整精度。20路8K输入加600输出的旧工程模型约21.5至22每路token/s，最后TTFT37.4秒。若各会话用满131K或262K，按15%缓存准备，三副本分别可容纳9份或3份。Onyx初次84.5至158加L，自建91.5至168.5。','知识库的检索能力建好后，可以作为公司Agent的一个工具。','9月方案预算及条件计算，经W1统一；性能未作设备实测校准。',cols=['项目','统一主方案'],rows=[['模型与辅助GPU','3×Qwen27回答副本＋1×embedding／reranker'],['应用与索引','2台CPU节点，各128GB ECC与镜像NVMe'],['20路短问答','8K输入＋600输出；每路约21.5–22.0 token/s（计算）'],['长会话驻留','131K：合计9份；262K：合计3份'],['首次平台／自建投入','84.5–158万元＋L ／ 91.5–168.5万元']],callout='NAS规模仍待盘点；首次入库、授权报价和运行费用单独预算。')
# 19–26 company
add('方案三　共享Agent','共享模型，各自保留任务与工具环境','Hermes组织多轮工作，Skills保存方法，MCP连接资料和系统','architecture','公司服务以DeepSeek为共享模型，员工或项目有各自任务目录与凭据。知识库统一提供授权检索，工具可以运行在员工电脑或集中CPU服务器。模型发出工具调用，应用执行并把结果返回模型。','共享模型首先要安排权重、Engram和每个会话的状态。','参考设计；工具执行位置与模型运行位置分别安排。',left=['员工／项目','Hermes会话','Skill与任务记录','独立目录与身份'],center=['共享推理服务','DeepSeek-V4.1-Flash','vLLM及所需适配'],right=['资料与工具','NAS授权检索','Python／业务接口','CPU执行与产物'],callout='目标规模：20路活动任务，长会话上限按1M规划。')
add('方案三　内存组成','权重、Engram和会话KV分别安排','模型固定占用与随会话增长的状态分开计算','table','官方原生checkpoint510.286GB，其中Engram202.758GB放主机内存，其余307.528GB是GPU权重分配的起点。Hopper全局KV为1827bytes/token/rank，一个1M会话每rank1.827GB。局部状态、草稿、工作区和图捕获由启动profile计入。1017配置与索引相同，保留原测量身份评估升级。','剩余显存能给二十个用户分到多少上下文？','官方原生制品；Hopper缓存按固定源码与启动池核算。',[SRC['deepseek'],SRC['ds1017']],cols=['资源','规模','主要位置'],rows=[['原生checkpoint','510.29GB','模型制品'],['Engram查找表','202.76GB／份','主机内存'],['其余权重','307.53GB','GPU分片及运行配置'],['每个1M会话全局KV','1.827GB／TP rank','参与推理的各GPU'],['其他运行状态','按实际启动与图捕获预算','局部缓存、草稿、工作区']],callout='Engram随模型实例安排；KV随保留会话和上下文增长。')
add('方案三　容量与布局','八卡H200可容纳二十份1M会话','按图捕获后的缓存预算估算，并预留10% token余量','table','统一容量口径下，20份会话H100 TP8每份242240，四H200 TP4每份762048；八H200 TP8或双TP4都能覆盖1M。若保留40份，TP8每份约636K，双TP4每份约762K。双TP4与TP8的模型副本和队列不同；同机DP可共享Engram，两独立serve则按两份预算。','工具执行期间任务仍保留上下文，需要把状态分层放置。','容量估算使用同一组post-graph预算；速度在下一部分单列。',cols=['配置','20份会话／每份','40份会话／每份'],rows=[['8×H100，TP8','约242K','约121K'],['4×H200，TP4','约762K','约381K'],['8×H200，TP8','1M（配置上限）','约636K'],['8×H200，双TP4','1M（配置上限）','约762K']],callout='同机TP4×DP2可共享一份Engram；两个独立TP4服务按两份计。')
add('方案三　会话分层','GPU运行当前任务，DRAM和SSD保存其他会话','20个生成请求＋20个等待工具请求，需要保留40份上下文','tiers','公司GPU显存和主机DRAM是独立物理资源。工具执行期间，把近期可复用状态保存在DRAM，较久未用的状态放SSD。下一轮在排队期间预取，模型继续处理新增输入。vLLM原生卸载适合比较单实例路径，LMCache MP提供独立缓存服务和跨实例管理。','下一步把缓存读取、输入处理和生成放在同一条时间线上。','来源：AI Infra Book 8.3／9.5与vLLM、LMCache文档。',[SRC['book'],SRC['offload'],SRC['lmcache']],tiers=[['GPU显存','正在生成的请求'],['CPU内存','近期会继续使用的状态'],['NVMe SSD','较久未使用的长会话']],side_title='运行方式',side=['本轮结束，保存可复用状态','工具返回，查找并预取缓存','新增输入prefill后继续生成'],callout='总会话数决定分层存储；同时生成数决定GPU计算负载。')
add('方案三　响应与吞吐','把首token等待拆成可计算的几个阶段','缓存读取、新增prefill、生成与工具执行各自计时','table','20路各20token/s需要系统400总decode。这是目标。已有H200 TP8 32会话AgentX回放为1052总输出、p95首token2.63秒，输入140至157K且约95%命中，草稿接受长度预设3.51。缓存读取算例中TP4的1M全局KV7.308GB，以24GB/s合计有效带宽为0.30秒；SSD6GB/s再入GPU为1.52秒；20份一起读取6.1秒。','有了容量和响应预算，再选择整机配置。','公开回放保持140K–157K身份；读取带宽24／6GB/s为假设。',cols=['问题','数值与统计范围'],rows=[['二十路生成目标','20×20＝400 token/s系统decode'],['公开H200 TP8回放','32会话，约1,052 token/s总输出，p95 TTFT 2.63秒'],['内存载入1M会话','TP4全局KV7.31GB；载荷传输约0.30秒'],['SSD经CPU载入','同一载荷约1.52秒；另计新增prefill'],['20份同时载入','总载荷146.16GB；约6.1秒']],callout='首token时间＝状态就绪与排队＋新增输入处理＋第一步生成。')
add('方案三　整机预算','完整服务器按卡型、互联和交付范围报价','八卡H200为主候选，A100结合已有设备评估复用','table','10月20日重新核验的境外挂牌与10月12日基线一致，人民币仍为含准备的分析预算。八A100翻新91至102万、八H100285至298、四H200NVL161至283、八H200291至304。设备所在地点、SKU、交易许可和支持共同决定实际交付。','A100路线还要明确采用怎样的推理引擎。','价格核验2026-10-20；人民币为分析预算，境外挂牌不等同境内成交。',[SRC['h200']],cols=['GPU与互联','CPU／主机内存','整机预算 万元'],rows=[['8×A100 80GB SXM，翻新','双EPYC 7V12／1TB','91–102'],['8×H100 80GB SXM／NVSwitch','双EPYC 9454／1.5TB','285–298'],['4×H200 NVL 141GB','双Xeon 6710E等级／1TB','161–283'],['8×H200 SXM 141GB／NVSwitch','双EPYC 9454／1.5TB','291–304']],callout='集中工具执行另需12–26万元CPU节点；已有终端可作为另一执行位置。')
add('方案三　A100引擎','公司A100采用modified vLLM','复用服务基础，按实际收益保留适配补丁','compare','shi3z以33到673token/s的自研迭代作为文章headline，特色在A100算子适配、按NVLink卡对安排通信和缓存与Graph协调。公司保留vLLM调度、分页缓存、接口和监控。Tokha八A800同机消融中，两项额外改动合计约4.5%，说明评价重点应是基线之上的增量。','将模型、引擎、工具和维护合为一套公司配置。','公开实验保留硬件、负载和统计范围；详细对照见备查页。',[SRC['shi'],SRC['tokha']],panels=[{'title':'沿用vLLM服务能力','value':'调度／缓存／接口','body':'请求队列、分页状态\n监控、部署与版本维护'},{'title':'维护必要硬件适配','value':'算子与通信补丁','body':'在目标机器上比较收益\n使用长任务与并发条件'}],callout='shi3z用于学习具体实现；公司部署以可维护的主流服务栈为基础。')
add('方案三　完整投入','模型服务器、工具环境和运行人员共同交付服务','硬件采购之外，实施与持续运行也是成本','table','公司中量TCO采用GPU整机预算中点297.36万，加18万工具节点、3万设施接入、45技术人日首次实施。每年60技术人日运维，以及机位、用电、软件支持。每项都在三年表里单独记录。首次硬件与实施和三年总额不同，不重复给已有CPU、RAM或保修加价。','接下来把三套方案放到同一张业务选择表中。','中量情景，技术人日2,500元；完整三年比较见后续成本页。',cols=['组成','配置／预算口径'],rows=[['模型服务器','8×H200；主机1.5TB；GPU整机291–304万元'],['任务执行','员工终端或集中CPU节点，新增12–26万元'],['应用与数据','Hermes、Skills／MCP、已有授权检索接口'],['首次实施','公司TCO基准45技术人日，11.25万元'],['持续运维','基准60技术人日／年，另计用电、机位与软件']],callout='主方案提供20×1M缓存容量候选，长期服务能力随真实任务负载核验。')
# 27–34 synthesis, economics, pilots
add('方案汇总','三种方式可以逐步组合','以工作范围和数据位置决定共享哪些资源','table','个人入口可以调用本地或共享模型。NAS知识库可以同时服务问答与Agent，权限维护只建设一套。已有CPU工具、NAS与模型资源在组合预算中只计一次。各方案的维护主体不同，选择不能只看单卡报价。','确定组合后，先划清资料和服务可以走哪条路径。',cols=['方式','获得的能力','主要投入','适合起步的任务'],rows=[['个人Spark','本地文件、代码、连续会话','设备＋少量实施维护','提取、表格、脚本与测试'],['权限知识库','统一检索、出处、撤权同步','接入、权限、索引和平台','部门资料问答'],['共享DeepSeek','较大模型、多用户工具任务','GPU、任务环境与运行管理','复杂财报分析与多轮任务']],callout='资料检索与工具可以复用，模型服务按质量和用量扩展。')
add('数据与运行','先确定资料范围，再比较本地与API','权限、工具、引用和模型变更覆盖整条工作链路','table','DeepSeek普通开放平台条款对商业秘密等输入输出有限制，因此本次API经济比较使用公开或符合条款且获准材料。Sonnet全球价格是适用主体和地域成立时的对照，大陆团队不能直接当作采购选项。内部系统按数据、身份、工具隔离、输出复核和变更治理落实责任。','在相同可用资料和验收要求下，逐轮计算成本。','公开规则核验2026-10-20；具体采用按数据、主体和交易条件落实。',[SRC['dterms'],SRC['aterms'],SRC['amac']],cols=['环节','实施动作'],rows=[['资料进入','按分类与协议确定本地／API路径'],['检索与引用','员工身份贯穿片段、下载、导出与撤权'],['模型与工具','固定版本，隔离目录、凭据和外发能力'],['输出交付','数字、引用、计算文件与测试结果一起复核'],['更新与运行','同一任务集回归，保留变更与处理记录']],callout='本地运行的价值包括资料与工具控制；经济性同时比较现金与人力投入。')
add('三年成本　计费基础','多轮任务要计算每次提交的完整输入','8轮任务从100K增长到170K，缓存读取继续计费','table','首轮100K，每轮新增8K工具输入，上轮输出2K进入历史，8轮累计提交1.08M输入、16K输出。新增外部156K已经包含在输入中。DeepSeek缓存读877800、未命中202200；Sonnet读864500、新写215500。计入10%额外轨迹后，token费约0.625和9.047元每计划任务。差异来自实际费率与缓存写读规则。','再把每项任务的费用放进三年的工作量与人员投入。','基准缓存假设：可复用历史95%命中；汇率7.00，API token费加6%准备。',[SRC['price'],SRC['claudeprice']],cols=['一份8轮轨迹','数量','处理方式'],rows=[['累计提交输入','1,080,000 tokens','分为缓存读、写或未命中'],['新增外部输入','156,000 tokens','已经包含在累计输入中'],['累计输出','16,000 tokens','含思考、工具参数与正文'],['DeepSeek每计划任务token费','约0.625元','含10%额外轨迹'],['Sonnet5.5每计划任务token费','约9.047元','全球对照，1小时缓存']],callout='模型消费之外，实施、工具、维护与审核仍需分别计入。')
