add('三年成本　中等使用量','中等工作量下，API预算低于新购本地设备','含实施与持续技术人工；个人与公司分别比较','dualchart','个人首年750任务、每年增10%，三年2482.5任务；公司20人首年25000、每年增25%，三年95312.5。个人本地9.05万、DeepSeek1.66万、Sonnet3.75万。公司本地392.54万、DeepSeek68.34万、Sonnet148.61万。公司API也计入相同18万元工具节点，基础应用和运维没有消失。不同模型按相同任务需求做预算情景，实际验收质量和复核差异要单独观察。','投入与使用量的关系，还要结合本地机器的处理能力。','单位万元；10/20费率与明确工作量假设。API资料／地域范围见前页。',[SRC['price'],SRC['claudeprice']],charts=[{'title':'个人：三年2,482.5项任务','categories':['Spark本地','DeepSeek API','Sonnet全球对照'],'values':[9.046564,1.655237,3.745960],'max':12,'unit':'万元'},{'title':'公司：三年95,312.5项任务','categories':['八H200本地','DeepSeek API','Sonnet全球对照'],'values':[392.541,68.3431,148.6138],'max':450,'unit':'万元'}],callout='公司本地GPU采购约占三年TCO的76%；当前token费率下，利用率很关键。')
add('三年成本　用量与扩容','任务量增加时，也要计算新增设备','按100K–170K轨迹的规划包络，比较低、中、高使用量','table','公司基准计算包络假设总decode400、未缓存prefill8000token/s，每年2000服务小时并留30%空间，得到每节点每年约64487计划任务。公司高量年任务5万、7.5万、11.25万，节点1→2→2，三年712.78万。此包络属于100K至170K轨迹规划，不是20路满1M实测。Spark对Sonnet的条件交点三年8376任务，对DeepSeek的交点远超单机能力；公司计入扩容后在扫描范围没有交叉。','成本以外，还要衡量每项业务实际节省了多少人工。','规划容量：400 decode＋8,000未缓存prefill token/s；2,000h／年，70%使用预算。',cols=['公司使用量','三年任务','GPU节点：逐年','本地／DeepSeek／Sonnet 万元'],rows=[['低','30,000','1 → 1 → 1','391.70 ／ 64.26 ／ 89.52'],['中','95,312.5','1 → 1 → 1','392.54 ／ 68.34 ／ 148.61'],['高','237,500','1 → 2 → 2','712.78 ／ 77.23 ／ 277.25']],callout='提高使用率可以分摊固定投入；跨过产能上限后，需要重新计扩容成本。')
add('试点与收益','先交付容易核对的字段、代码和比较表','公开能力、实施依赖和失败影响共同决定优先级','table','公告提取与代码辅助可先开展，财报比较复用这些组件，NAS问答先完成身份与撤权链路，材料预审待规则与错例积累。技术实施按2500元人日；分析师工时价值按150元小时是另一种角色成本。公司中量若每项净省15分钟，三年释放23828小时，工时价值357.42万元；是否成为现金收益取决于实际费用变化。','公开跑分可以帮助选模型，业务产物还需要有清楚的验收方法。','人日和时间节省均为规划输入；设备与平台统一分摊，工时价值与现金分开。',cols=['顺序／任务','首期技术人日','实施估算 万元','主要交付'],rows=[['1 公告提取','8–12','2.0–3.0','字段表＋证据与错例'],['2 代码与测试','6–10','1.5–2.5','代码diff＋独立测试'],['3 财报比较','12–20','3.0–5.0','计算表＋摘要与引用'],['4 NAS授权问答','25–45','6.25–11.25','有限目录＋权限验收'],['5 材料预审储备','15–25','3.75–6.25','规则与审核样例']],callout='净节省工时＝原人工时间－辅助操作、复核和返工时间。')
add('能力与验收','公开评测用于筛选，业务验收对应具体产物','同一基准内比较；字段、引用、计算和过程分别检查','table','本轮以网上已有评测为主，不新增模型调用。Qwen27在ExtractBench短文94.68、长文38.45value F1，提示完整提取要分段并检查遗漏。AA-LCR约100K多文档问答82%，不是1M窗口质量。FinanceAgent提供金融研究证据，BizBench给出过程与最终成功的差别。我们准备了12个虚构任务及gold或验收清单，供后续复用。','最后把部署和试点安排落实为连续的实施顺序。','原榜任务／pipeline各有条件；所有比较保留版本和指标名称。',[SRC['extract'],SRC['aa'],SRC['finance'],SRC['biz']],cols=['公开证据','对本项目的含义','后续业务验收'],rows=[['字段提取pipeline','短文提取适合起步，长列表易漏','关键字段、数量、单位、证据'],['金融研究与多文档QA','筛选Qwen、DeepSeek与GLM对照','期间口径、事实覆盖、引用'],['终端与代码任务','以测试验证代码产物','原测试、边界错误、可复跑'],['多步骤任务','结果与执行过程分别检查','权限、只读边界、工具记录']],callout='已准备12个虚构种子任务；运行后的人工时间和资源消耗接入TCO。')
add('最终安排','按业务依赖逐步扩展本地LLM应用','从个人可核对任务开始，逐步连接共享资料和模型','roadmap','建议前三步：前两周公告提取与代码辅助，三至五周复用组件形成财报比较，五至八周接入一个部门的NAS授权问答。共享GPU的新增采购应由数据范围、真实使用量和服务要求共同支持。已有可用且获准的模型系统可以先承担试点，模型端点可替换。最终需要业务和IT确认任务量、资料身份、可用设备和等待目标。','正文结束，附录用于进一步讨论配置、成本和来源。','时间为项目启动后的规划；技术资源与业务验收按各方案落实。',steps=[['第1–2周','公告提取＋代码辅助','字段、测试、人工时间'],['第3–5周','财报比较与摘要','计算文件、口径、引用'],['第5–8周','部门NAS授权问答','身份、撤权、运维交接']],callout='先确认任务和资料，再用质量、等待与三年成本决定共享GPU规模。')
